using System.Diagnostics;
using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using CommerceErp.Core;
using CommerceErp.Infrastructure;
string Op()=>Guid.NewGuid().ToString("N");
var output=Path.GetFullPath(args[0]);var repo=Path.GetFullPath(args[1]);Directory.CreateDirectory(Path.GetDirectoryName(output)!);var root=Path.Combine(Path.GetTempPath(),"CommerceErp.InventoryDocs",Op());Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
void Assert(bool ok,string message="断言失败"){if(!ok)throw new Exception(message);}
void Throws<T>(Action f)where T:Exception{try{f();}catch(T){return;}throw new Exception("未抛出"+typeof(T).Name);}
async Task Test(string name,Func<Task> f){try{await f();results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;results.Add(new{name,passed=false,error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e);}}
Task Sync(Action a){a();return Task.CompletedTask;}
(CommerceDatabase Db,InventoryDocumentService Docs,OrderService Orders) Fresh(){var db=new CommerceDatabase(Path.Combine(root,Op()));return(db,new(db),new(db));}
InventoryDocumentLine Line(InventoryDocumentService s,string sku,decimal value,decimal q=0){var b=s.GetBalance(sku);return new(sku,value,q,b.Version,b.QuarantineVersion,b.SkuVersion);}
InventoryDocumentRequest Request(InventoryDocumentKind kind,params InventoryDocumentLine[] lines)=>new(Op(),Op(),kind,lines.ToList(),"测试原因","合成实物核对凭证");
InventoryDocumentResult Post(InventoryDocumentService s,InventoryDocumentRequest r){var doc=s.Create(r);return s.Approve(doc.Id,new(Op(),doc.Version,"核对审核"));}
void Healthy(InventoryDocumentService d,OrderService o){Assert(d.Audit().Passed&&o.CheckConsistency().Passed&&o.AuditAfterSales().Passed,"库存/隔离/单据核对失败");}
await Test("草稿不改库存且请求重放只建一单",()=>Sync(()=>{var(_,d,o)=Fresh();var r=Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",3));var doc=d.Create(r);Assert(d.Create(r).Replayed&&d.List().Total==1&&o.Inventory().Single(x=>x.SkuId=="sku-shirt").OnHand==100);Healthy(d,o);}));
await Test("正负调整正确入账，重复审核原请求只入账一次",()=>Sync(()=>{var(_,d,o)=Fresh();var doc=d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",3.125m)));var action=new InventoryDocumentAction(Op(),1,"审核");d.Approve(doc.Id,action);Assert(d.Approve(doc.Id,action).Replayed&&d.GetBalance("sku-shirt").OnHand==103.125m);Throws<ConflictException>(()=>d.Approve(doc.Id,action with{OperationId=Op()}));Post(d,Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",-2)));Assert(d.GetBalance("sku-shirt").OnHand==101.125m);Healthy(d,o);}));
await Test("盘点含良品与隔离实盘，零差异可留核对记录",()=>Sync(()=>{var(_,d,o)=Fresh();var posted=Post(d,Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",97,4)));Assert(d.GetBalance("sku-shirt").OnHand==97&&d.GetBalance("sku-shirt").Quarantined==4&&d.Details(posted.Id).Movements.Single().QuarantineDelta==4);var same=Post(d,Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",97,4)));Assert(d.Details(same.Id).Movements.Single().OnHandDelta==0);Healthy(d,o);}));
await Test("隔离转良品、报损、退供均保留数量去向",()=>Sync(()=>{var(_,d,o)=Fresh();Post(d,Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",100,10)));Post(d,Request(InventoryDocumentKind.QuarantineRelease,Line(d,"sku-shirt",3)));Post(d,Request(InventoryDocumentKind.QuarantineScrap,Line(d,"sku-shirt",2)));Post(d,Request(InventoryDocumentKind.QuarantineReturn,Line(d,"sku-shirt",1)));Assert(d.GetBalance("sku-shirt").OnHand==103&&d.GetBalance("sku-shirt").Quarantined==4);Healthy(d,o);}));
await Test("负库存、超额隔离、数量精度与重复SKU被拒绝",()=>Sync(()=>{var(_,d,_)=Fresh();Throws<BusinessRuleException>(()=>d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",-101))));Throws<BusinessRuleException>(()=>d.Create(Request(InventoryDocumentKind.QuarantineScrap,Line(d,"sku-shirt",1))));Throws<BusinessRuleException>(()=>d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",0.0001m))));var line=Line(d,"sku-shirt",1);Throws<BusinessRuleException>(()=>d.Create(Request(InventoryDocumentKind.Adjustment,line,line)));Throws<BusinessRuleException>(()=>d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",decimal.MinValue))));}));
await Test("冻结量和预占量不能被盘亏或调整占用",()=>Sync(()=>{var(_,d,o)=Fresh();var stock=d.GetBalance("sku-shirt");o.Policy("sku-shirt",new(Op(),stock.Version,20,0,"冻结"));Throws<BusinessRuleException>(()=>d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",-81))));var id=o.Import(new(Op(),SeedData.BaseOrder(Platform.Douyin)));var b=d.GetBalance("sku-shirt");Throws<BusinessRuleException>(()=>d.Create(Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",b.Reserved+b.Frozen-1,b.Quarantined))));Healthy(d,o);}));
await Test("库存变化和隔离变化均使旧盘点失效",()=>Sync(()=>{var(_,d,o)=Fresh();var first=d.Create(Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",90,0)));o.Receive("sku-shirt",new(Op(),1,"并发收货"));Throws<ConflictException>(()=>d.Approve(first.Id,new(Op(),1,"旧单审核")));var second=d.Create(Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",90,0)));Post(d,Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",101,2)));Throws<ConflictException>(()=>d.Approve(second.Id,new(Op(),1,"隔离变化")));Healthy(d,o);}));
await Test("草稿更正刷新版本，作废与已审核修改受保护",()=>Sync(()=>{var(_,d,o)=Fresh();var doc=d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",2)));var edit=new EditInventoryDocumentRequest(Op(),1,[Line(d,"sku-shirt",5)],"改正","新凭证");d.Edit(doc.Id,edit);Assert(d.Edit(doc.Id,edit).Replayed);Throws<ConflictException>(()=>d.Void(doc.Id,new(Op(),1,"旧版本")));d.Void(doc.Id,new(Op(),2,"作废"));Throws<ConflictException>(()=>d.Approve(doc.Id,new(Op(),3,"禁止")));var approved=Post(d,Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",1)));Throws<ConflictException>(()=>d.Edit(approved.Id,new(Op(),2,[],"禁止","凭证")));Healthy(d,o);}));
await Test("多行中途故障整单余额流水事件回滚，原键恢复成功",()=>Sync(()=>{var(db,d,o)=Fresh();var doc=d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",3),Line(d,"sku-mug",2)));var before=CommerceDatabase.Json(o.Inventory());var events=db.Read(x=>x.Scalar<int>("SELECT COUNT(*) FROM Outbox"));var action=new InventoryDocumentAction(Op(),1,"审核");Throws<InvalidOperationException>(()=>new InventoryDocumentService(db,s=>{if(s=="after-line")throw new InvalidOperationException();}).Approve(doc.Id,action));Assert(CommerceDatabase.Json(o.Inventory())==before&&d.Details(doc.Id).Movements.Count==0&&db.Read(x=>x.Scalar<int>("SELECT COUNT(*) FROM Outbox"))==events);d.Approve(doc.Id,action);Healthy(d,o);}));
await Test("冲销生成反向草稿，原单流水保留且只允许一次冲销",()=>Sync(()=>{var(_,d,o)=Fresh();var original=Post(d,Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",5)));var reverse=d.Reverse(original.Id,new(Op(),2,Op(),"更正原单","实物确认"));Assert(d.GetBalance("sku-shirt").OnHand==105);d.Approve(reverse.Id,new(Op(),1,"复核冲销"));Assert(d.GetBalance("sku-shirt").OnHand==100&&d.Details(original.Id).Document.State=="Reversed"&&d.Details(original.Id).Movements.Count==1);Throws<ConflictException>(()=>d.Reverse(original.Id,new(Op(),3,Op(),"重复","凭证")));Throws<ConflictException>(()=>d.Reverse(reverse.Id,new(Op(),2,Op(),"冲销的冲销","凭证")));Healthy(d,o);}));
await Test("隔离处置冲销恢复原隔离余额并回退良品",()=>Sync(()=>{var(_,d,o)=Fresh();Post(d,Request(InventoryDocumentKind.Count,Line(d,"sku-shirt",100,5)));var release=Post(d,Request(InventoryDocumentKind.QuarantineRelease,Line(d,"sku-shirt",2)));var reverse=d.Reverse(release.Id,new(Op(),2,Op(),"复检更正","实物退回隔离"));d.Approve(reverse.Id,new(Op(),1,"审核"));Assert(d.GetBalance("sku-shirt").Quarantined==5&&d.GetBalance("sku-shirt").OnHand==100);Healthy(d,o);}));
await Test("并发审核共享旧版本库存只允许一单成功",async()=>{var(_,d,o)=Fresh();var a=d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",-60)));var b=d.Create(Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",-60)));var winners=await Task.WhenAll(new[]{a,b}.Select(doc=>Task.Run(()=>{try{d.Approve(doc.Id,new(Op(),1,"并发审核"));return true;}catch(ConflictException){return false;}})));Assert(winners.Count(x=>x)==1&&d.GetBalance("sku-shirt").OnHand==40);Healthy(d,o);});
await Test("冲销不能减少后来已冻结的库存",()=>Sync(()=>{var(_,d,o)=Fresh();var original=Post(d,Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",5)));o.Policy("sku-shirt",new(Op(),d.GetBalance("sku-shirt").Version,105,0,"冻结全部"));Throws<BusinessRuleException>(()=>d.Reverse(original.Id,new(Op(),2,Op(),"冲销","核对")));Healthy(d,o);}));
await Test("分页筛选、单号唯一、变更操作号内容冲突",()=>Sync(()=>{var(_,d,_)=Fresh();var r=Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",1));d.Create(r);Throws<ConflictException>(()=>d.Create(r with{OperationId=Op()}));Throws<ConflictException>(()=>d.Create(r with{Reason="不同内容"}));Assert(d.List(size:1,state:"Draft").Total==1);Throws<BusinessRuleException>(()=>d.List(size:201));}));
await Test("9到10升级不改原库存、身份和审核配置，重复打开无变化",()=>Sync(()=>{var(db,d,o)=Fresh();var identity=db.InstanceId;var before=CommerceDatabase.Json(o.Inventory());db.Write(x=>x.Execute("ALTER TABLE InventoryLedger DROP COLUMN StockDocumentId;DROP TABLE InventoryReversals;DROP TABLE InventoryMovements;DROP TABLE InventoryDocumentHistory;DROP TABLE InventoryDocuments;DELETE FROM SchemaMigrations WHERE Version=10;"));var upgraded=new CommerceDatabase(Path.GetDirectoryName(db.DatabasePath)!);Assert(upgraded.InstanceId==identity&&CommerceDatabase.Json(new OrderService(upgraded).Inventory())==before&&new MasterDataService(upgraded).GetOpeningPolicy().Version==0);_=new CommerceDatabase(Path.GetDirectoryName(db.DatabasePath)!);Assert(new InventoryDocumentService(upgraded).List().Total==0);}));
await Test("历史退货隔离库存处置及冲销保留售后流水",()=>Sync(()=>{var dir=Path.Combine(root,Op());Directory.CreateDirectory(dir);File.Copy(Path.Combine(repo,"tests/Fixtures/stage5-v4.db"),Path.Combine(dir,"commerce.db"));var db=new CommerceDatabase(dir);var d=new InventoryDocumentService(db);var o=new OrderService(db);var q=o.Quarantine().First(x=>x.Quantity>0);var before=d.GetBalance(q.SkuId);var oldLedger=db.Read(x=>x.Scalar<int>("SELECT COUNT(*) FROM QuarantineLedger"));var release=Post(d,Request(InventoryDocumentKind.QuarantineRelease,Line(d,q.SkuId,Math.Min(1,q.Quantity))));Healthy(d,o);var reverse=d.Reverse(release.Id,new(Op(),2,Op(),"复检更正","实物退回"));d.Approve(reverse.Id,new(Op(),1,"审核"));Assert(d.GetBalance(q.SkuId).Quarantined==before.Quarantined&&db.Read(x=>x.Scalar<int>("SELECT COUNT(*) FROM QuarantineLedger"))==oldLedger);Healthy(d,o);}));
await Test("仅有隔离流水的商品禁止改单位或组合结构，停用后不能转良品",()=>Sync(()=>{var db=new CommerceDatabase(Path.Combine(root,Op()),new("正式库存测试","主仓"));var m=new MasterDataService(db);var sku=m.SaveSku(new(Op(),null,0,"ISOLATED","隔离品","件",true,[],"建立"));var d=new InventoryDocumentService(db);var o=new OrderService(db);Post(d,Request(InventoryDocumentKind.Count,Line(d,sku.Id,0,3)));Throws<ConflictException>(()=>m.SaveSku(new(Op(),sku.Id,1,"ISOLATED","隔离品","箱",true,[],"改单位")));var release=d.Create(Request(InventoryDocumentKind.QuarantineRelease,Line(d,sku.Id,1)));m.SaveSku(new(Op(),sku.Id,1,"ISOLATED","隔离品","件",false,[],"停用"));Throws<ConflictException>(()=>d.Approve(release.Id,new(Op(),1,"审核")));Healthy(d,o);}));
await Test("两个冲销草稿只有一个可入账，原单永不重复冲销",async()=>{var(_,d,o)=Fresh();var original=Post(d,Request(InventoryDocumentKind.Adjustment,Line(d,"sku-shirt",5)));var a=d.Reverse(original.Id,new(Op(),2,Op(),"冲销A","凭证"));var b=d.Reverse(original.Id,new(Op(),2,Op(),"冲销B","凭证"));var wins=await Task.WhenAll(new[]{a,b}.Select(x=>Task.Run(()=>{try{d.Approve(x.Id,new(Op(),1,"审核"));return true;}catch(ConflictException){return false;}})));Assert(wins.Count(x=>x)==1&&d.GetBalance("sku-shirt").OnHand==100);Healthy(d,o);});
// Real HTTP verifies server identity, role boundaries, independent approval and durable replay.
var httpDb=new CommerceDatabase(Path.Combine(root,"http"));var accounts=new AccountService(httpDb);accounts.Setup(new("inv-admin","管理员","Inventory-Admin-2026!"));var token=Op()+Op();var config=Path.Combine(root,"server.json");await File.WriteAllTextAsync(config,JsonSerializer.Serialize(new{listenAddress="127.0.0.1",port=0,databaseProvider="Sqlite",dataDirectory=Path.GetDirectoryName(httpDb.DatabasePath)}));var psi=new ProcessStartInfo("dotnet"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};psi.ArgumentList.Add(Path.Combine(repo,"src/CommerceErp.Api/bin/Release/net10.0/CommerceErp.Api.dll"));psi.ArgumentList.Add("--server");psi.ArgumentList.Add(config);psi.Environment["ERP_SESSION_TOKEN"]=token;using var host=Process.Start(psi)!;var errors=host.StandardError.ReadToEndAsync();using var http=new HttpClient();http.DefaultRequestHeaders.Add("X-Erp-Session",token);
async Task<T> Send<T>(string path,object body){using var res=await http.PostAsJsonAsync(path,body,ErpJson.Options);var text=await res.Content.ReadAsStringAsync();Assert(res.IsSuccessStatusCode,path+": "+(int)res.StatusCode+" "+text);return JsonSerializer.Deserialize<T>(text,ErpJson.Options)!;}
async Task Login(string name,string password){http.DefaultRequestHeaders.Authorization=null;var r=await Send<LoginResult>("/api/security/login",new LoginRequest(name,password));http.DefaultRequestHeaders.Authorization=new("Bearer",r.Token);}
try{
using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(30));while(await host.StandardOutput.ReadLineAsync(timeout.Token) is{} line)if(line.StartsWith("ERP_READY|")){http.BaseAddress=new Uri(line[10..]);break;}Assert(http.BaseAddress is not null);var allShops=SeedData.Platforms.Select(x=>SeedData.Shop(x.Id)).ToList();foreach(var(name,role)in new[]{("inv-warehouse",AccountRole.Warehouse),("inv-approver",AccountRole.InventoryApprover),("inv-observer",AccountRole.Observer)})accounts.Save(null,new(name,"合成账号",role,SeedData.Tenant,true,0,allShops,[BusinessUnits.Warehouse],"授权","Inventory-Initial-2026!"));
foreach(var name in new[]{"inv-warehouse","inv-approver","inv-observer"}){await Login(name,"Inventory-Initial-2026!");await Send<JsonElement>("/api/security/password",new ChangePasswordRequest("Inventory-Initial-2026!","Inventory-Changed-2026!"));}
var docs=new InventoryDocumentService(httpDb);InventoryDocumentResult? draft=null;InventoryDocumentAction? approval=null;
await Test("HTTP仓储建单不能审核、观察员不能写，审核员不能制单",async()=>{await Login("inv-warehouse","Inventory-Changed-2026!");draft=await Send<InventoryDocumentResult>("/api/inventory-documents",Request(InventoryDocumentKind.Adjustment,Line(docs,"sku-shirt",2)));Assert((await http.PostAsJsonAsync($"/api/inventory-documents/{draft.Id}/approve",new InventoryDocumentAction(Op(),1,"越权"),ErpJson.Options)).StatusCode==HttpStatusCode.Forbidden);await Login("inv-observer","Inventory-Changed-2026!");Assert((await http.GetAsync("/api/inventory-documents")).IsSuccessStatusCode&&(await http.PostAsJsonAsync("/api/inventory-documents",Request(InventoryDocumentKind.Adjustment,Line(docs,"sku-shirt",1)),ErpJson.Options)).StatusCode==HttpStatusCode.Forbidden);await Login("inv-approver","Inventory-Changed-2026!");Assert((await http.PostAsJsonAsync("/api/inventory-documents",Request(InventoryDocumentKind.Adjustment,Line(docs,"sku-shirt",1)),ErpJson.Options)).StatusCode==HttpStatusCode.Forbidden);});
await Test("HTTP独立审核真实账号入账且原请求重放幂等",async()=>{await Login("inv-approver","Inventory-Changed-2026!");approval=new(Op(),1,"审核核对");await Send<InventoryDocumentResult>($"/api/inventory-documents/{draft!.Id}/approve",approval);Assert((await Send<InventoryDocumentResult>($"/api/inventory-documents/{draft.Id}/approve",approval)).Replayed&&docs.GetBalance("sku-shirt").OnHand==102&&docs.Details(draft.Id).Document.ApprovedBy==accounts.Accounts().Single(x=>x.Username=="inv-approver").Id);});
await Test("HTTP管理员不能审核自己创建或修改的单据",async()=>{await Login("inv-admin","Inventory-Admin-2026!");var own=await Send<InventoryDocumentResult>("/api/inventory-documents",Request(InventoryDocumentKind.Adjustment,Line(docs,"sku-shirt",1)));Assert(!(await http.PostAsJsonAsync($"/api/inventory-documents/{own.Id}/approve",new InventoryDocumentAction(Op(),1,"自己审核"),ErpJson.Options)).IsSuccessStatusCode);await Login("inv-warehouse","Inventory-Changed-2026!");var other=await Send<InventoryDocumentResult>("/api/inventory-documents",Request(InventoryDocumentKind.Adjustment,Line(docs,"sku-shirt",1)));await Login("inv-admin","Inventory-Admin-2026!");await Send<InventoryDocumentResult>($"/api/inventory-documents/{other.Id}/edit",new EditInventoryDocumentRequest(Op(),1,[Line(docs,"sku-shirt",2)],"管理员修改","凭证"));Assert(!(await http.PostAsJsonAsync($"/api/inventory-documents/{other.Id}/approve",new InventoryDocumentAction(Op(),2,"修改人审核"),ErpJson.Options)).IsSuccessStatusCode);});
await Test("HTTP不同账号不能接管原审核操作号",async()=>{await Login("inv-admin","Inventory-Admin-2026!");Assert((await http.PostAsJsonAsync($"/api/inventory-documents/{draft!.Id}/approve",approval,ErpJson.Options)).StatusCode==HttpStatusCode.Forbidden);Healthy(docs,new OrderService(httpDb));});
}
finally{if(!host.HasExited){host.Kill(true);await host.WaitForExitAsync();}await errors;}
await File.WriteAllTextAsync(output,JsonSerializer.Serialize(new{passed=failed==0,total=results.Count,failed,checks=results},ErpJson.Options));return failed==0?0:1;
